  "Ich habe noch einen Kinogutschein von Weihnachten.": "Kam ende një kupon kinemaje nga Krishtlindjet.",
  "Nehmen wir Reihe zwölf, schön mittig.": "Le të marrim rreshtin dymbëdhjetë, mu në mes.",
  "Ganz vorne bekomme ich immer Nackenschmerzen.": "Krejt përpara më dhemb gjithmonë qafa.",
  "Die Vorstellung ist fast ausverkauft, nur noch Randplätze.": "Shfaqja është gati plot, kanë mbetur vetëm vende anash.",
  "Einmal Popcorn, süß und salzig gemischt.": "Një porcion kokoshka, të ëmbla e të kripura bashkë.",
  "Die Werbung dauert hier immer zwanzig Minuten.": "Reklamat këtu zgjasin gjithmonë njëzet minuta.",
  "Die Vorschau war besser als mancher Film.": "Traileri ishte më i mirë se shumë filma.",
  "Auf welchem Platz sitzen wir? — Zwölf und dreizehn.": "Në cilat vende jemi? — Dymbëdhjetë dhe trembëdhjetë.",
  "Entschuldigung, ich glaub Sie sitzen auf unseren Plätzen.": "Më falni, më duket se jeni ulur në vendet tona.",
  "Entschuldigung, ich glaube, Sie sitzen auf unseren Plätzen.": "Më falni, më duket se jeni ulur në vendet tona.",
  "Entschuldigung, ich glaub, Sie sitzen auf unseren Plätzen.": "Më falni, më duket se jeni ulur në vendet tona.",
  "Entschuldigung, ich glaube Sie sitzen auf unseren Plätzen.": "Më falni, më duket se jeni ulur në vendet tona.",
  "Kannst du das Handy ausmachen? Es leuchtet.": "Mund ta fikësh celularin? Po ndriçon.",
  "Nicht flüstern — erzähl es mir nachher!": "Mos pëshpërit — më trego më pas!",
  "Die Leinwand hier ist riesig.": "Ekrani këtu është gjigant.",
  "Der Saal war früher mal ein Theater.": "Salla dikur ka qenë teatër.",
