  "Ich schaue Filme am liebsten in der Originalfassung.": "Filmat më pëlqen t'i shoh në versionin origjinal.",
  "Mit Untertiteln versteh ich fast alles.": "Me titra kuptoj pothuajse gjithçka.",
  "Mit Untertiteln verstehe ich fast alles.": "Me titra kuptoj pothuajse gjithçka.",
  "Die Verfilmung ist gut, aber das Buch ist besser.": "Përshtatja filmike është e mirë, por libri është më i mirë.",
  "Kein Spoiler, bitte — ich hab ihn noch nicht gesehen!": "Mos më trego asgjë, të lutem — s'e kam parë ende!",
  "Kein Spoiler, bitte — ich habe ihn noch nicht gesehen!": "Mos më trego asgjë, të lutem — s'e kam parë ende!",
  "Beim traurigen Ende haben alle geschnieft.": "Në fundin e trishtë të gjithë u përlotën.",
  "Wir bleiben bis zum Ende vom Abspann sitzen.": "Rrimë ulur deri në fund të titrave.",
  "Nach dem Abspann kam noch eine Extraszene.": "Pas titrave erdhi edhe një skenë shtesë.",
