  "Für die Jahreszahlen habe ich eine Eselsbrücke.": "Për vitet kam një truk për t'i mbajtur mend.",
  "Eselsbrücken sind albern und genau deshalb unvergesslich.": "Truket e tilla janë qesharake — dhe pikërisht për këtë nuk harrohen.",
